const VOICE_DATA = {"file":"voice/voices.mp3","lines":{"c1":{"who":"AKURO","text":"Tell me, boy...","mono":false,"off":0.25,"dur":1.131,"env":"0014599797887447899755543321000000"},"c2":{"who":"AKURO","text":"...what is it you want to break?","mono":false,"off":1.7807,"dur":1.6,"env":"003577976864357424674678763223246664321000000000"},"c3":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":3.7807,"dur":1.579,"env":"069725972119666547873054555554577642110000000000"},"e1":{"who":"TAKUTO","text":"Two-fourteen. Last freight of the night.","mono":true,"off":5.7593,"dur":2.155,"env":"02365111589610324443321112566653421005543411344444311000000000000"},"e2":{"who":"TAKUTO","text":"Same crossing. Same bell.","mono":true,"off":8.314,"dur":1.856,"env":"00115876654112898632233321100122755455316653211000000000"},"e3":{"who":"TAKUTO","text":"Same cat.","mono":true,"off":10.57,"dur":0.981,"env":"002269776541178764210000000000"},"e4":{"who":"TAKUTO","text":"It was Haruki's cat first. He fed it every night on his way home.","mono":true,"off":11.9513,"dur":4.587,"env":"026626552213799876653101023334332011454200110676311023200000000000002421179848523562244455555433200134443321343433224555321000000000000000"},"e5":{"who":"TAKUTO","text":"Two years now.","mono":true,"off":16.938,"dur":1.088,"env":"033586435789743156564322110000000"},"e6":{"who":"TAKUTO","text":"So I bring the cat food. Somebody has to.","mono":true,"off":18.426,"dur":2.837,"env":"01347798942676654024764101114654322110000000023398664775544334555643420122210000000000"},"e7":{"who":"TAKUTO","text":"Tuna. The expensive kind. Don't tell anyone.","mono":false,"off":21.6633,"dur":3.008,"env":"1327776765215678314510676523363101146766332221000000001896412457775335554333211000000000000"},"e8":{"who":"TAKUTO","text":"Grandma used to say I was born to carry things for other people.","mono":true,"off":25.0713,"dur":4.245,"env":"00178899885468776542236654512445444755543100046653543111377776544222201145554430004543333231125304534420112432001210000000000000"},"e9":{"who":"TAKUTO","text":"...What is it?","mono":false,"off":29.7167,"dur":0.896,"env":"013469937763335331000000000"},"e10":{"who":"TAKUTO","text":"The bell... There's no train.","mono":true,"off":31.0127,"dur":1.728,"env":"0342189988754200054433355554203224544321100000000000"},"e11":{"who":"TAKUTO","text":"...Okay. No.","mono":false,"off":33.1407,"dur":1.131,"env":"0005992123887555566654221110000000"},"e12":{"who":"???","text":"Don't come near it!","mono":false,"off":34.6713,"dur":1.173,"env":"053995102336988877775422210240000000"},"e13":{"who":"TAKUTO","text":"Hey!","mono":false,"off":36.2447,"dur":0.576,"env":"003999865432100000"},"e14":{"who":"TAKUTO","text":"Get down!","mono":false,"off":37.2207,"dur":0.768,"env":"026400397665432211000000"},"a1":{"who":"TAKUTO","text":"...Two moons.","mono":true,"off":38.3887,"dur":1.024,"env":"0102479866899875433222221000000"},"a2":{"who":"TAKUTO","text":"Okay. That's new.","mono":true,"off":39.8127,"dur":1.259,"env":"05897122799872887124256665311100000000"},"a3":{"who":"TAKUTO","text":"And I'm holding... an axe?","mono":true,"off":41.4713,"dur":1.792,"env":"025588776531599884254322100000045421566321002332100000"},"a4":{"who":"TAKUTO","text":"Where the hell am I?","mono":true,"off":43.6633,"dur":1.173,"env":"005964843489976665545432111000000000"},"a5":{"who":"NEMU","text":"Hnnnaaah... Oh. You're alive. Neat.","mono":false,"off":45.2367,"dur":2.603,"env":"0474203441144554200100000000000028986432103444424433322110000000346642000031000"},"a6":{"who":"TAKUTO","text":"You were lying on train tracks a minute ago.","mono":false,"off":48.2393,"dur":2.411,"env":"0035499469888776555554142365555323156543114344554434213654211000000000000"},"a7":{"who":"NEMU","text":"Mm. I'm very good at that.","mono":false,"off":51.05,"dur":2.005,"env":"0259777665543210000000002498722665554022663420033221100030000"},"a8":{"who":"NEMU","text":"Lying places. Getting squished.","mono":false,"off":53.4553,"dur":2.496,"env":"002789999977414055542221322112210000000000003799377743332116653111333102000"},"a9":{"who":"TAKUTO","text":"Where is this?","mono":false,"off":56.3513,"dur":1.045,"env":"01378998999532179642122210000000"},"a10":{"who":"NEMU","text":"The Barrow Fields. Edge of the Ashen March.","mono":false,"off":57.7967,"dur":3.371,"env":"006409977666641111454431000013320000000000000000000299885213314211642037764243345555544321100013321000"},"a11":{"who":"NEMU","text":"You fell out of the sky.","mono":false,"off":61.5673,"dur":1.664,"env":"00993211199987532004886450114453412465432211000000"},"a12":{"who":"NEMU","text":"People like you have a name here. Skyfallen.","mono":false,"off":63.6313,"dur":3.435,"env":"00419903688668887302247635751777788888652125421110000000000000000000000001345344998851111544322121000000"},"a13":{"who":"TAKUTO","text":"There are others?","mono":false,"off":67.466,"dur":1.045,"env":"01687889820698275432222210000000"},"a14":{"who":"NEMU","text":"A few. Most of them land worse.","mono":false,"off":68.9113,"dur":2.389,"env":"053101138885200000000000589983424400145432222455555441024432100024332000"},"a15":{"who":"TAKUTO","text":"...I'll take that as a compliment.","mono":false,"off":71.7007,"dur":1.856,"env":"00057896034699610008765554443013665302443221000000000000"},"a16":{"who":"NEMU","text":"...Hey.","mono":false,"off":73.9567,"dur":0.747,"env":"00211149987533210000000"},"a17":{"who":"NEMU","text":"Where did you get that axe?","mono":false,"off":75.1033,"dur":1.515,"env":"0018939614683248620026542103775321000122331000"},"a18":{"who":"TAKUTO","text":"It was sticking out of a grave. I grabbed it on the way down.","mono":false,"off":77.018,"dur":3.605,"env":"0452446530295013444444223211365554221000000000000000256321168766831144333344343243333124444322100000000000000"},"a19":{"who":"NEMU","text":"That's the Headsman's Axe.","mono":false,"off":81.0233,"dur":1.536,"env":"02787213205833796142266653430487421000112210000"},"a20":{"who":"NEMU","text":"It's been stuck in that grave for three hundred years.","mono":false,"off":82.9593,"dur":3.541,"env":"06503203986532222115742000105654543000104443211110000000000000000000142001137773146542431123432100001321000"},"a21":{"who":"NEMU","text":"People tried pulling it out with horses.","mono":false,"off":86.9007,"dur":2.859,"env":"02158403551033117765432110010000000000021899997665366654300004121045542443111101222000"},"a22":{"who":"TAKUTO","text":"...It was loose.","mono":false,"off":90.1593,"dur":1.024,"env":"0037655632445987521112111000000"},"a23":{"who":"NEMU","text":"WHY WAS IT LOOSE?!","mono":false,"off":91.5833,"dur":1.237,"env":"00279984289535620048974201333310000000"},"a24":{"who":"NEMU","text":"Rifts open in the sky. Things crawl out.","mono":false,"off":93.2207,"dur":3.243,"env":"01897101012310189730035332344443322234432211000000000000000000000018876644111165443333221100020000"},"a25":{"who":"NEMU","text":"We call them Fiends.","mono":false,"off":96.8633,"dur":1.472,"env":"009604339999229663111178865431111333300000000"},"a26":{"who":"NEMU","text":"Swords don't bite them. Arrows bounce off.","mono":false,"off":98.7353,"dur":3.413,"env":"0122376666553033146863103544421001211210000000000000000000000269976665433320055555542331422211100110000"},"a27":{"who":"NEMU","text":"Normal people can't do anything but run.","mono":false,"off":102.5487,"dur":3.072,"env":"000688887754102214420021100000000000012147641005344003986641002222110000023210156533210000000"},"a28":{"who":"NEMU","text":"Unless you have a Brand.","mono":false,"off":106.0207,"dur":1.515,"env":"0298766664122222101542353031034454321000002000"},"a29":{"who":"NEMU","text":"A mark on your soul. It wakes up when you're about to die... if you have one.","mono":false,"off":107.9353,"dur":5.824,"env":"0049877767775410001006976566445443533221000000000000000000000000000000000492102887103332675300104676665632654310423145533322110000000000000000175121552225455210011110000000000"},"a30":{"who":"NEMU","text":"Branded people become Hunters. They hunt Fiends for the Guild.","mono":false,"off":114.1593,"dur":4.416,"env":"0257888654520002044012321102320214544211165523311000003432000000000000000000000001352126973010000689775433333200413302444321100010000"},"a31":{"who":"TAKUTO","text":"And people without one?","mono":false,"off":118.9753,"dur":1.557,"env":"00575043665116985357427788740134543110000000000"},"a32":{"who":"NEMU","text":"Get very good at running.","mono":false,"off":120.9327,"dur":1.579,"env":"004761111289977873003288764341007886332110000000"},"a33":{"who":"NEMU","text":"Mine's called Nine Lives.","mono":false,"off":122.9113,"dur":1.728,"env":"0038999864453032575510045977776433443321100000544100"},"a34":{"who":"NEMU","text":"I can die nine times. I've used six.","mono":false,"off":125.0393,"dur":3.456,"env":"03695032887358766666544665666542411434321111002320000000000000000000002696012798534102323553100021221000"},"a35":{"who":"TAKUTO","text":"Six.","mono":false,"off":128.8953,"dur":0.661,"env":"00112697630011100000"},"a36":{"who":"NEMU","text":"Don't make the face.","mono":false,"off":129.9567,"dur":1.323,"env":"0489987410387611014311145432110122221000"},"a37":{"who":"TAKUTO","text":"I'm not making a face.","mono":false,"off":131.6793,"dur":1.536,"env":"00477766899923663124454110498631111322100000000"},"a38":{"who":"NEMU","text":"You're making it with your eyes.","mono":false,"off":133.6153,"dur":1.792,"env":"005997767777103145443201004111243203654321100002332000"},"a39":{"who":"TAKUTO","text":"That thing at the crossing. Was it chasing you?","mono":false,"off":135.8073,"dur":2.709,"env":"0016971001976672151125898743223221100000001475365102433865332244433322110000000000"},"a40":{"who":"NEMU","text":"I was digging for grave silver. It woke up. Shieldbearers don't wake up.","mono":false,"off":138.9167,"dur":5.675,"env":"023787345321049921565541113100225665555134231443210221110000000000000000000015710167740033432100010000000000000000000002344389873006543333321233005774203553023332100010000"},"a41":{"who":"NEMU","text":"Then the ground opened. Rifts open in the sky... not into other worlds.","mono":false,"off":144.9913,"dur":5.909,"env":"0038866546111566555444443015630031100001000000000000000000000000017974100002230000687400344332444334322023343222111100000000000000000000036644321353313026614431233221100001222000"},"a42":{"who":"NEMU","text":"Somebody opened that one.","mono":false,"off":151.3007,"dur":1.963,"env":"02223688754654413210000000000697203555414443200011111100000"},"a43":{"who":"TAKUTO","text":"...You hear that?","mono":false,"off":153.6633,"dur":0.981,"env":"002464237799358754320001000000"},"a44":{"who":"NEMU","text":"A bell. There are no bells out here.","mono":false,"off":155.0447,"dur":2.133,"env":"0262099875320000000000012239987999820676544365342212211532111000"},"b1":{"who":"NEMU","text":"Run. I mean it this time.","mono":false,"off":157.578,"dur":1.685,"env":"004998754200000035876689966300243434141322111000000"},"b2":{"who":"TAKUTO","text":"You said that at the crossing.","mono":false,"off":159.6633,"dur":1.6,"env":"013433359842276655301301146554322121100000000000"},"b3":{"who":"NEMU","text":"And you didn't listen! I only have three left!","mono":false,"off":161.6633,"dur":2.837,"env":"00034553681540258443311210000000000000000002563069888762245521101136553333211000002000"},"b4":{"who":"TAKUTO","text":"Then stay behind me.","mono":false,"off":164.9007,"dur":1.493,"env":"004886745411998652673224665554332110000000000"},"b5":{"who":"NEMU","text":"Don't hit the shield! Nothing breaks the shield!","mono":false,"off":166.794,"dur":2.773,"env":"032641113930024443326654211010000000000000016997311887643665113200444315432110010000"},"b6":{"who":"TAKUTO","text":"Then what do I hit?!","mono":false,"off":169.9673,"dur":1.216,"env":"0045555994014667754313553100121000000"},"b7":{"who":"NEMU","text":"Nothing! We run!","mono":false,"off":171.5833,"dur":1.045,"env":"00698311688741006741665321000000"},"b8":{"who":"TAKUTO","text":"Can't... get up...","mono":true,"off":173.0287,"dur":1.301,"env":"0012488787630121498667864300000000000000"},"b9":{"who":"NEMU","text":"Hey! Ugly!","mono":false,"off":174.73,"dur":0.896,"env":"001577642001895223331100000"},"b10":{"who":"NEMU","text":"Over here!","mono":false,"off":176.026,"dur":0.789,"env":"039822642217875422100000"},"b11":{"who":"TAKUTO","text":"Wait!","mono":false,"off":177.2153,"dur":0.555,"env":"02798654101100000"},"b12":{"who":"TAKUTO","text":"Born to carry things for other people.","mono":true,"off":178.17,"dur":2.432,"env":"0116999887535401257766552110665444434213541553553011344200232110000000000"},"b13":{"who":"TAKUTO","text":"Groceries. Grudges. Blame.","mono":true,"off":181.002,"dur":2.027,"env":"0003799843323344432200147874212443220003455543210000000000000"},"b14":{"who":"TAKUTO","text":"Not this. I'm not carrying this one.","mono":true,"off":183.4287,"dur":2.261,"env":"01346785000489633321003444454310114444443333233231023210000000000000"},"b15":{"who":"AKURO","text":"Finally.","mono":false,"off":186.09,"dur":0.875,"env":"002499767576554554211000000"},"b16":{"who":"AKURO","text":"Three hundred years in the dirt, and this is who pulls me out?","mono":false,"off":187.3647,"dur":3.968,"env":"000145675543358854369532347775788532245555421368898542000000245554567743333211356433224431001355454213454445543221000000"},"b17":{"who":"TAKUTO","text":"Who are you?","mono":false,"off":191.7327,"dur":0.981,"env":"000177699865323664311000000000"},"b18":{"who":"AKURO","text":"The reason the axe was stuck.","mono":false,"off":193.114,"dur":1.792,"env":"013995566676534766575435666421125432221477642100000000"},"b19":{"who":"AKURO","text":"Tell me, boy. What is it you want to break?","mono":false,"off":195.306,"dur":2.411,"env":"0134577989986446889986553201235886995554223686566522221477653320001100000"},"b20":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":198.1167,"dur":1.579,"env":"069725972119666547873054555554577642110000000000"},"b21":{"who":"AKURO","text":"...Good answer.","mono":false,"off":200.0953,"dur":1.088,"env":"013379877645777643334654432100000"},"b22":{"who":"TAKUTO","text":"It was in the way.","mono":false,"off":201.5833,"dur":1.195,"env":"047526955697867653378974211000000000"},"b23":{"who":"NEMU","text":"Hnnaaah... Ow.","mono":false,"off":203.178,"dur":1.579,"env":"029751044312655542222210000000000199865321000000"},"b24":{"who":"TAKUTO","text":"You were dead.","mono":false,"off":205.1567,"dur":0.96,"env":"00246457521498775421100000000"},"b25":{"who":"NEMU","text":"Mm. That's seven. Two left.","mono":false,"off":206.5167,"dur":2.261,"env":"02897776665443100035310332245410311000000000033286534433211000002000"},"b26":{"who":"TAKUTO","text":"Don't do that again.","mono":false,"off":209.178,"dur":1.301,"env":"0017986312467367653431155432110000000000"},"b27":{"who":"NEMU","text":"You're making the face.","mono":false,"off":210.8793,"dur":1.323,"env":"0019978887720336543411114432110012222000"},"b28":{"who":"TAKUTO","text":"I'm making it with my whole face this time.","mono":false,"off":212.602,"dur":2.688,"env":"006887778998101465554212420256554115899741111764434320243430245543210000000000000"},"b29":{"who":"TAKUTO","text":"...I never asked your name.","mono":false,"off":215.69,"dur":1.515,"env":"0004677679726976555450124455555321100000000000"},"b30":{"who":"NEMU","text":"Nemu.","mono":false,"off":217.6047,"dur":0.832,"env":"0001899886678754201110000"},"b31":{"who":"NEMU","text":"And you're the idiot who pulled out the Headsman's Axe.","mono":false,"off":218.8367,"dur":3.179,"env":"016655576640330006961321110001000000000000005202135541554300142124411330443332124321000012221000"},"b32":{"who":"TAKUTO","text":"Takuto. Kirishima Takuto.","mono":false,"off":222.4153,"dur":2.389,"env":"015763016412599864210001353444534544444420144420023102355421110000000000"},"b33":{"who":"SIEG","text":"Well, well, well.","mono":false,"off":225.2047,"dur":1.515,"env":"0597655665357877555556664100788776544322100000"},"b34":{"who":"SIEG","text":"A Shieldbearer's shield. Broken in one swing.","mono":false,"off":227.1193,"dur":3.051,"env":"07964445976666557666665333325666664444320000000000987631576545667766665553222068654332221000"},"b35":{"who":"SIEG","text":"Twelve years I've been hunting. Never seen that.","mono":false,"off":230.57,"dur":3.264,"env":"12597655576566556555420000046775347666423765532675443310000000049976567643224876766555443210110000"},"b36":{"who":"SIEG","text":"Nice axe, kid. Mind telling me where you got it?","mono":false,"off":234.234,"dur":3.136,"env":"08976676431046764202330028987643410000000009976666664234966677777665666677535866663244201110000"},"b37":{"who":"TAKUTO","text":"It was loose.","mono":false,"off":237.77,"dur":0.981,"env":"155357433457986321111110000000"},"b38":{"who":"NEMU","text":"He keeps saying that.","mono":false,"off":239.1513,"dur":1.472,"env":"000950326970343348987665545533221012000000000"},"b39":{"who":"SIEG","text":"Ha! It was loose, he says.","mono":false,"off":241.0233,"dur":1.835,"env":"02797766665310464587689897677522100198621887554432100000"},"b40":{"who":"SIEG","text":"You two had better come with me. Because that...","mono":false,"off":243.258,"dur":2.901,"env":"0697632328655556668655416555664102575455565311665444300000000385289764357665431022110000"},"b41":{"who":"SIEG","text":"...is not supposed to stay open.","mono":false,"off":246.5593,"dur":2.027,"env":"0598789765631132862198666753001575320777652477751065433221000"},"b42":{"who":"AKURO","text":"We're going to have so much fun, you and I.","mono":false,"off":248.986,"dur":2.603,"env":"0149736887643454577633444697756743321136765552321013489865664223555432211000000"},"s1":{"who":"SABLE","text":"One fell through.","mono":false,"off":251.9887,"dur":1.856,"env":"00022479775221246443223311133322222100000000000000000000"},"s2":{"who":"SABLE","text":"...Good.","mono":false,"off":254.2447,"dur":1.045,"env":"01211442137976432220111111100000"},"p1":{"who":"TAKUTO","text":"Next time: the Hunters' Guild.","mono":false,"off":255.69,"dur":1.856,"env":"03699415403699987655355337873246543202997632110000000000"},"p2":{"who":"TAKUTO","text":"A test that reads my rank as ERROR...","mono":false,"off":257.946,"dur":2.24,"env":"14103279833105631244421214544432445443013332102445432111000000000000"},"p3":{"who":"TAKUTO","text":"...and a girl with a red scarf who hates me on sight.","mono":false,"off":260.586,"dur":3.029,"env":"0004777522599999843530442236673124430156775421123322454301303443333313335531100000000000000"},"p4":{"who":"TAKUTO","text":"Why does she have my hair?","mono":false,"off":264.0153,"dur":1.557,"env":"00258988484543445576213544442145542111000000000"},"p5":{"who":"TAKUTO","text":"Episode two. Branded.","mono":false,"off":265.9727,"dur":1.749,"env":"05610543369874104337553211000002676656532221000000000"}}};
